            'story.title': 'Our Story | NUBIE',
            'story.overline': 'Our Story',
            'story.lead': 'We believe being new is not a weakness.<br>It is the first proof of courage.',
            'story.p1': 'nubie was born from a simple belief: you do not need to be fully ready to begin.',
            'story.p2': 'In a world that often celebrates perfection, confidence, and experience, we wanted to create a brand that speaks to the moment before all of that — the moment you choose to start, even when you are still unsure.',
            'story.p3': 'Our name comes from “newbie” — a word often used for someone who is just starting out. But to us, being new is not something to hide. It is something to honor.',
            'story.p4': 'Because every expert, every rebel, every creator, and every unforgettable person began as someone new.',
            'story.p5': 'We started fragrance because scent stays close to who we are. It is invisible, but unforgettable. A scent can mark a beginning, hold a memory, and become part of how someone carries themselves into the world.',
            'story.p6': 'We are not here to romanticize starting small. We are here to prove that something new can still be intentional, crafted, and uncompromising in quality.',
            'story.p7': 'From formula to packaging, from content to service, every detail of nubie is created to carry the same belief: starting is not a small thing. It is the beginning of becoming.',
            'story.p8': 'nubie is for those who are brave enough to begin again.',
