            'craft.weighingLabel': 'WEIGHING — CLOSE UP',
            'craft.processOverline': 'The Process',
            'craft.processTitle': 'We do not create fragrances, we create a presence.',
            'craft.processText': 'Born first as a thought shaped by emotion and belief, each scent becomes a representative of who we are, designed not only to be smelled, but to be felt, lived, and to speak without words.',
            'craft.ingredientsOverline': 'Ingredients',
            'craft.ingredientsTitle': 'Natural & Synthetic',
            'craft.ingredientsQuote': '"We use both natural and synthetic materials. Not because one is better — because each does something the other can\'t."',
            'craft.naturalTitle': 'Natural',
            'craft.naturalText': 'Extracted from plants, resins, and flowers. Naturals carry the full complexity of their origin — no two batches are identical. That variation is part of what makes them interesting.',
            'craft.syntheticTitle': 'Synthetic',
            'craft.syntheticText': 'Created in a lab to isolate or invent specific olfactive qualities. Synthetics let us be precise — a molecule that smells exactly like warm skin, clean wood, or nothing found in nature at all.',
