            'story.title': 'เรื่องราวของเรา | NUBIE',
            'story.overline': 'เรื่องราวของเรา',
            'story.lead': 'เราเชื่อว่าการเป็นมือใหม่ไม่ใช่จุดอ่อน<br>แต่มันคือหลักฐานแรกของความกล้า',
            'story.p1': 'nubie เกิดจากความเชื่อง่ายๆ ว่า คุณไม่จำเป็นต้องพร้อมสมบูรณ์แบบก่อนที่จะเริ่ม',
            'story.p2': 'ในโลกที่มักยกย่องความสมบูรณ์แบบ ความมั่นใจ และประสบการณ์ เราอยากสร้างแบรนด์ที่พูดกับช่วงเวลาก่อนสิ่งเหล่านั้น — ช่วงเวลาที่คุณเลือกจะเริ่ม แม้ยังไม่แน่ใจทั้งหมด',
            'story.p3': 'ชื่อของเรามาจากคำว่า “newbie” — คำที่มักใช้เรียกคนที่เพิ่งเริ่มต้น แต่สำหรับเรา การเป็นคนใหม่ไม่ใช่สิ่งที่ต้องซ่อน มันคือสิ่งที่ควรให้เกียรติ',
            'story.p4': 'เพราะผู้เชี่ยวชาญทุกคน ครีเอเตอร์ทุกคน และคนที่น่าจดจำทุกคน ล้วนเคยเริ่มจากการเป็นคนใหม่',
            'story.p5': 'เราเริ่มจากน้ำหอม เพราะกลิ่นอยู่ใกล้ตัวตนของเรามาก มันมองไม่เห็น แต่ก็ลืมไม่ลง กลิ่นสามารถแสดงถึงการเริ่มต้น เก็บความทรงจำ และกลายเป็นส่วนหนึ่งของวิธีที่เราพาตัวเองออกไปสู่โลก',
            'story.p6': 'เราไม่ได้อยู่ตรงนี้เพื่อทำให้การเริ่มจากเล็กๆ เราอยู่ตรงนี้เพื่อพิสูจน์ว่าสิ่งใหม่ยังสามารถถูกรังสรรค์เป็นอย่างดี และไม่ประนีประนอมเรื่องคุณภาพได้',
            'story.p7': 'ตั้งแต่สูตร กล่อง ไปจนถึงการบริการ ทุกรายละเอียดของ nubie ถูกสร้างขึ้นเพื่อถือความเชื่อเดียวกัน: การเริ่มต้นไม่ใช่เรื่องเล็ก มันคือจุดเริ่มของการกลายเป็นตัวเอง',
            'story.p8': 'nubie คือพื้นที่สำหรับคนที่กล้าพอจะเริ่มใหม่อีกครั้ง',
