            'privacy.intro': 'นโยบายความเป็นส่วนตัวนี้อธิบายว่า Nubie เก็บรวบรวม ใช้ จัดเก็บ เปิดเผย และปกป้องข้อมูลส่วนบุคคลของคุณอย่างไร เมื่อคุณเยี่ยมชมเว็บไซต์ สั่งซื้อสินค้า ติดต่อเรา สร้างบัญชี เข้าร่วมโปรแกรมสมาชิก หรือมีปฏิสัมพันธ์กับแบรนด์ของเรา<br><br>การใช้เว็บไซต์หรือการให้ข้อมูลส่วนบุคคลแก่ Nubie ถือว่าคุณรับทราบว่าได้อ่านและเข้าใจนโยบายความเป็นส่วนตัวนี้แล้ว',
