        'Additional shipping fees may apply for reshipment.': 'อาจมีค่าจัดส่งเพิ่มเติมสำหรับการจัดส่งซ้ำ',
        'Lost or Delayed Parcels': 'พัสดุสูญหายหรือล่าช้า',
        'If your parcel appears delayed or lost, please contact us with your order number and tracking number.': 'หากพัสดุของคุณดูเหมือนล่าช้าหรือสูญหาย โปรดติดต่อเราพร้อมหมายเลขคำสั่งซื้อและเลขติดตามพัสดุ',
        'Nubie will help coordinate with the shipping carrier, but investigation timelines and final decisions may depend on the carrier’s process.': 'Nubie จะช่วยประสานงานกับบริษัทขนส่ง แต่ระยะเวลาการตรวจสอบและการตัดสินใจขั้นสุดท้ายอาจขึ้นอยู่กับขั้นตอนของบริษัทขนส่ง',
