        'Nubie is not responsible for customs delays, import restrictions, rejected parcels, or additional charges imposed by local authorities.': 'Nubie ไม่รับผิดชอบต่อความล่าช้าจากศุลกากร ข้อจำกัดการนำเข้า พัสดุที่ถูกปฏิเสธ หรือค่าใช้จ่ายเพิ่มเติมที่กำหนดโดยหน่วยงานท้องถิ่น',
