        'Governing Law': 'กฎหมายที่ใช้บังคับ',
        'Nubie is a fragrance brand offering fragrance mist and related products. Our brand belief is that being new is not a weakness, but a form of courage.': 'Nubie เป็นแบรนด์น้ำหอมที่นำเสนอสเปรย์น้ำหอมและผลิตภัณฑ์ที่เกี่ยวข้อง ความเชื่อของแบรนด์เราคือการเป็นมือใหม่ไม่ใช่จุดอ่อน แต่เป็นรูปแบบหนึ่งของความกล้าหาญ',
        'Website owner / operator: Nattawut Rahethan': 'เจ้าของ/ผู้ดำเนินการเว็บไซต์: Nattawut Rahethan',
        'Brand name: Nubie': 'ชื่อแบรนด์: Nubie',
