        'Selected product only': 'เฉพาะสินค้าที่กำหนด',
        'Use your Marks to unlock rewards that make your next start feel even better.': 'ใช้ Mark ของคุณปลดล็อกรางวัลที่ทำให้การเริ่มต้นครั้งต่อไปรู้สึกดียิ่งขึ้น',
        'Red Ribbon Wrap + Sample': 'ห่อริบบิ้นแดง + ตัวอย่างน้ำหอม',
        'Add our signature red ribbon gift wrapping and a 2ml discovery sample to your next order.': 'เพิ่มการห่อของขวัญริบบิ้นแดงซิกเนเจอร์และตัวอย่างน้ำหอมขนาด 2ml ในคำสั่งซื้อถัดไปของคุณ',
        'Discovery Set (4x2ml)': 'Discovery Set (4x2ml)',
