        'Priority': 'ก่อนใคร',
        'Mark Rules': 'กฎของ Mark',
        'To keep the Circle fair for every member, Mark Rewards are subject to simple rules.': 'เพื่อความยุติธรรมสำหรับสมาชิกทุกคนใน Circle รางวัล Mark อยู่ภายใต้กฎง่ายๆ ดังนี้',
        'Marks are available only for registered Nubie accounts.': 'Mark ใช้ได้เฉพาะบัญชี Nubie ที่ลงทะเบียนแล้วเท่านั้น',
        'Marks cannot be exchanged for cash.': 'Mark ไม่สามารถแลกเปลี่ยนเป็นเงินสดได้',
        'Marks cannot be transferred to another account.': 'Mark ไม่สามารถโอนไปยังบัญชีอื่นได้',
        'Marks may be deducted if an order is canceled, returned, or refunded.': 'Mark อาจถูกหักหากคำสั่งซื้อถูกยกเลิก คืนสินค้า หรือคืนเงิน',
        'Marks from purchases are calculated from the paid product value, excluding shipping fees and discounts.': 'Mark จากการซื้อสินค้าคำนวณจากมูลค่าสินค้าที่ชำระจริง ไม่รวมค่าจัดส่งและส่วนลด',
        'Some rewards may have minimum order requirements.': 'รางวัลบางรายการอาจมีเงื่อนไขยอดซื้อขั้นต่ำ',
        'Some rewards are available while stocks last.': 'รางวัลบางรายการมีให้จนกว่าสินค้าจะหมด',
        'Nubie may adjust Mark rules, earning rates, or tier benefits with reasonable notice.': 'Nubie อาจปรับกฎของ Mark อัตราการสะสม หรือสิทธิประโยชน์ระดับสมาชิก โดยจะแจ้งให้ทราบตามความเหมาะสม',
        'Abuse, fraud, fake accounts, or suspicious activity may result in account suspension or Mark removal.': 'การใช้งานผิดเงื่อนไข การทุจริต บัญชีปลอม หรือพฤติกรรมน่าสงสัย อาจส่งผลให้บัญชีถูกระงับหรือ Mark ถูกถอน',
        'When your friend makes their first Nubie purchase, you both get rewarded. Invite as many friends as you want — earn milestone rewards for the first three who purchase.': 'เมื่อเพื่อนของคุณสั่งซื้อ Nubie ครั้งแรก ทั้งคู่จะได้รับรางวัล ชวนเพื่อนได้ไม่จำกัดจำนวน และรับรางวัลตามเป้าหมายสำหรับเพื่อน 3 คนแรกที่สั่งซื้อ',
        '15% Off': 'ส่วนลด 15%',
