        'Both of you receive a 15% discount code. As you hit milestones, unlock gift codes for physical rewards.': 'ทั้งคู่จะได้รับรหัสส่วนลด 15% เมื่อคุณถึงเป้าหมาย จะปลดล็อกรหัสของขวัญสำหรับรางวัลจริง',
        'Use your codes at checkout — discount codes for % off, gift codes to claim physical sets with your order.': 'ใช้รหัสของคุณตอนชำระเงิน — รหัสส่วนลดสำหรับลดราคา รหัสของขวัญสำหรับรับเซ็ตของจริงพร้อมคำสั่งซื้อ',
